{"content": "// Proper string-literal scanner over the minified bundle, then dup analysis on prompt-like text.
const fs = require('fs');
const B = 'C:/Users/UserX/AppData/Local/Programs/ZCode/resources/glm/zcode.cjs';
const src = fs.readFileSync(B, 'utf8');

function scan(src) {
  const out = [];
  let i = 0;
  const n = src.length;
  while (i < n) {
    const c = src[i];
    if (c === '/' && src[i + 1] === '/') { while (i < n && src[i] !== '\n') i++; continue; }
    if (c === '/' && src[i + 1] === '*') { i += 2; while (i < n && !(src[i] === '*' && src[i + 1] === '/')) i++; i += 2; continue; }
    if (c === '/' && src[i + 1] === '=') { i += 2; while (i < n && src[i] !== '/') i++; i++; continue; }
    if (c === '/' && src[i + 1] === '^') { i += 2; while (i < n && src[i] !== '/') i++; i++; continue; }
    if (c === '"' || c === "'" || c === '`') {
      const q = c; const start = i; i++;
      let buf = '';
      while (i < n) {
        const d = src[i];
        if (d === '\\') { buf += d + (src[i + 1] || ''); i += 2; continue; }
        if (d === q) { i++; break; }
        if (q === '`' && d === '$' && src[i + 1] === '{') {
          // skip balanced template expression
          let depth = 1; i += 2;
          while (i < n && depth > 0) {
            if (src[i] === '{') depth++;
            else if (src[i] === '}') depth--;
            else if (src[i] === '\\') i++;
            i++;
          }
          buf += '\u0000'; continue;
        }
        buf += d; i++;
      }
      out.push({ start, end: i, q, body: buf });
      continue;
    }
    i++;
  }
  return out;
}

const lits = scan(src);
console.log('total string literals:', lits.length);

function dec(s) {
  return s.replace(/\\n/g, '\n').replace(/\\t/g, '\t').replace(/\\r/g, '\r')
    .replace(/\\'/g, "'").replace(/\\"/g, '"').replace(/\\`/g, '`')
    .replace(/\\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/\\\\/g, '\\');
}

const PROMPT_HINT = /(\bYou are\b|\bThe user\b|\btool\b|\bprompt\b|\bskill\b|\bwrite\b|\bmust\b|\bdo not\b|\bWhen\b|\buse this\b|^#{1,4} |\n#{1,4} )/;
const CODE_HINT = /(function\s*\(|=>\s*\{|require\(|exports\.|;\s*let\s|===|typeof\s)/;

const prose = [];
for (const l of lits) {
  const t = dec(l.body);
  if (t.length < 300) continue;
  const words = (t.match(/[A-Za-z]{2,}/g) || []).length;
  if (words < 40) continue;
  const codeScore = (t.match(/[{};()=><]/g) || []).length / t.length;
  if (codeScore > 0.15) continue;               // skip source code
  if (!PROMPT_HINT.test(t)) continue;
  const first = t.split('\n').map(s => s.trim()).filter(Boolean)[0] || '(blank)';
  prose.push({ start: l.start, len: t.length, first: first.slice(0, 120), text: t });
}

console.log('prompt-like literals:', prose.length);
const total = prose.reduce((a, r) => a + r.len, 0);
console.log('prompt payload chars:', total, '~tokens(/4):', Math.round(total / 4));

// normalization + dup detection
const norm = s => s.replace(/\s+/g, ' ').trim();
const groups = new Map();
for (const r of prose) {
  const k = norm(r.text);
  if (!groups.has(k)) groups.set(k, []);
  groups.get(k).push(r);
}
const dups = [...groups.entries()].filter(([, v]) => v.length > 1);
console.log('\nEXACT duplicate prompt literals (identical after whitespace normalization):', dups.length);
let dupWaste = 0;
dups.sort((a, b) => b[0].length * (b[1].length - 1) - a[0].length * (a[1].length - 1))
  .forEach(([k, v]) => {
    const waste = k.length * (v.length - 1);
    dupWaste += waste;
    console.log(`  x${v.length} len=${k.length} waste~${waste} chars | ${k.slice(0, 100)}`);
  });
console.log('exact-dup wasted chars:', dupWaste, '~tokens:', Math.round(dupWaste / 4));

// near-duplicate detection via paragraph shingles (find repeated prose blocks >= 200 chars)
const paraMap = new Map();
for (const r of prose) {
  for (const p of r.text.split(/\n{2,}/)) {
    const np = norm(p);
    if (np.length < 200) continue;
    if (!paraMap.has(np)) paraMap.set(np, []);
    paraMap.get(np).push(r.start);
  }
}
const pdup = [...paraMap.entries()].filter(([, v]) => v.length > 1);
const pWaste = pdup.reduce((a, [k, v]) => a + k.length * (v.length - 1), 0);
console.log('\nEXACT duplicate paragraphs (>=200 chars) across literals:', pdup.length, 'wasted chars:', pWaste, '~tokens:', Math.round(pWaste / 4));
pdup.sort((a, b) => b[0].length * (b[1].length - 1) - a[0].length * (a[1].length - 1)).slice(0, 30)
  .forEach(([k, v]) => console.log(`  x${v.length} len=${k.length} waste~${k.length * (v.length - 1)} | ${k.slice(0, 130)}`));

fs.mkdirSync('C:/Users/UserX/.zcode/workspace/default/zc_out', { recursive: true });
fs.writeFileSync('C:/Users/UserX/.zcode/workspace/default/zc_out/prompts.json', JSON.stringify(prose.map(r => ({ start: r.start, len: r.len, first: r.first })), null, 1));
fs.writeFileSync('C:/Users/UserX/.zcode/workspace/default/zc_out/paras.json', JSON.stringify(pdup.map(([k, v]) => ({ count: v.length, len: k.length, text: k.slice(0, 2000) })), null, 1));
console.log('\nwrote zc_out/');
