{"content": "// Cross-plugin duplication analysis over markdown/prompt/setup files.
const fs = require('fs'), path = require('path'), crypto = require('crypto');
const ROOT = 'C:/Users/UserX/.zcode/cli/plugins/cache/zcode-plugins-official';
const EXT = new Set(['.md', '.txt', '.ps1', '.sh', '.json']);

function walk(d, out = []) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) { if (!/node_modules|__pycache__/.test(p)) walk(p, out); }
    else if (EXT.has(path.extname(e.name))) out.push(p);
  }
  return out;
}

const files = walk(ROOT);
const norm = s => s.replace(/\r\n/g, '\n').replace(/[ \t]+/g, ' ').trim();

// 1) exact duplicate whole files (content-normalized)
const byHash = new Map();
for (const f of files) {
  const buf = fs.readFileSync(f);
  let k;
  if (/\.(md|txt|ps1|sh)$/.test(f)) k = 'n:' + crypto.createHash('sha1').update(norm(buf.toString('utf8'))).digest('hex');
  else k = 'b:' + crypto.createHash('sha1').update(buf).digest('hex');
  if (!byHash.has(k)) byHash.set(k, []);
  byHash.get(k).push(f);
}
console.log('=== EXACT DUPLICATE FILES (whole file identical) ===');
let totalWaste = 0;
[...byHash.entries()].filter(([, v]) => v.length > 1)
  .map(([k, v]) => ({ k, v, size: fs.statSync(v[0]).size }))
  .sort((a, b) => b.size * (b.v.length - 1) - a.size * (a.v.length - 1))
  .forEach(({ k, v, size }) => {
    const w = size * (v.length - 1);
    totalWaste += w;
    console.log(`x${v.length}  ${size} bytes each  waste=${w}`);
    v.forEach(f => console.log('     ' + f.replace(ROOT + '\\', '').replace(ROOT + '/', '')));
  });
console.log('total redundant bytes from whole-file dups:', totalWaste, '~tokens:', Math.round(totalWaste / 4));

// 2) duplicated contiguous blocks (>=400 chars) across DIFFERENT files
const MIN = 400;
const blocks = new Map(); // normalized block -> Set(files)
for (const f of files) {
  if (!/\.(md|txt|ps1|sh)$/.test(f)) continue;
  const t = norm(fs.readFileSync(f, 'utf8'));
  const paras = t.split(/\n{2,}/).map(s => s.trim()).filter(s => s.length >= MIN);
  for (const p of paras) {
    if (!blocks.has(p)) blocks.set(p, new Set());
    blocks.get(p).add(f);
  }
}
console.log('\n=== DUPLICATED PARAGRAPH BLOCKS (>=400 normalized chars, across different files) ===');
const crossDup = [...blocks.entries()].filter(([, s]) => s.size > 1);
let crossWaste = 0;
crossDup.map(([p, s]) => {
  let bytes = 0; for (const f of s) bytes += Math.max(0, fs.statSync(f).size);
  return { p, s, waste: p.length * (s.size - 1) };
}).sort((a, b) => b.waste - a.waste).forEach(({ p, s, waste }) => {
  crossWaste += waste;
  console.log(`x${s.size} len=${p.length} waste~${waste}`);
  console.log('     "' + p.slice(0, 150).replace(/\n/g, ' ') + '"');
  [...s].forEach(f => console.log('       ' + f.replace(ROOT + '\\', '..').replace(ROOT + '/', '..')));
});
console.log('total redundant chars from cross-file paragraph dups:', crossWaste, '~tokens:', Math.round(crossWaste / 4));

// 3) per-plugin totals
console.log('\n=== PER-PLUGIN PROMPT PAYLOAD (md/txt only) ===');
const per = {};
for (const f of files) {
  if (!/\.(md|txt)$/.test(f)) continue;
  const rel = path.relative(ROOT, f).split(path.sep)[0];
  per[rel] = (per[rel] || 0) + fs.statSync(f).size;
}
Object.entries(per).sort((a, b) => b[1] - a[1]).forEach(([k, v]) => console.log(k.padEnd(28), v, 'bytes ~', Math.round(v / 4), 'tok'));
