const fs = require('fs');
const B = 'C:/Users/UserX/AppData/Local/Programs/ZCode/resources/glm/zcode.cjs';
const src = fs.readFileSync(B, 'utf8');

function dec(s) {
  return s.replace(/\\n/g, '\n').replace(/\\t/g, '\t').replace(/\\r/g, '\r')
    .replace(/\\'/g, "'").replace(/\\"/g, '"').replace(/\\`/g, '`')
    .replace(/\\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/\\\\/g, '\\');
}

function extractAt(marker, mode) {
  const at = src.indexOf(marker);
  if (at < 0) return null;
  // walk back to enclosing quote
  let i = at, q = null;
  while (i >= 0) {
    const c = src[i];
    if (c === '"' || c === "'" || c === '`') {
      // ensure not escaped
      let bs = 0, j = i - 1;
      while (j >= 0 && src[j] === '\\') { bs++; j--; }
      if (bs % 2 === 0) { q = c; break; }
    }
    i--;
  }
  if (!q) return null;
  const start = i + 1;
  // walk forward respecting escapes
  let k = start, buf = '';
  while (k < src.length) {
    const c = src[k];
    if (c === '\\') { buf += src[k] + (src[k + 1] || ''); k += 2; continue; }
    if (c === q) break;
    buf += c; k++;
  }
  return { start, end: k, q, len: buf.length, text: dec(buf) };
}

