  ['TodoRead', 'Read the current session todo list'],
  ['Skill', 'Execute a skill within the main conversation'],
  ['CronCreate', 'Create a persistent scheduled automation'],
  ['CronDelete', 'Delete a scheduled automation'],
  ['CronUpdate', 'Update selected definition fields of an existing scheduled automation'],
  ['OffPeakCreate', 'Create a one-off idle-time task'],
  ['SendMessage', 'Send a message to another agent'],
  ['Workflow', 'Create and run a dynamic workflow'],
  ['AmendWorkflow', 'Amend an existing dynamic-workflow run'],
  ['ListModels', 'Lists the models this host has configured'],
  ['ReadSessionContext', 'Read relevant or handoff context from another persisted ZCode session'],
  ['Reboot', 'Reboot the system'],
];

const out = [];
for (const [name, marker] of MARKERS) {
  const r = extractAt(marker);
  if (!r) { console.log('MISS  ' + name); continue; }
  const first = r.text.split('\n').map(s => s.trim()).filter(Boolean)[0] || '';
