const lines = fs.readFileSync(DIR + '/' + file, 'utf8').split('\n').filter(Boolean);
const rec = JSON.parse(lines[lines.length - 1]);
const body = rec.request.body;
const tools = body.tools;

const rows = tools.map(t => {
  const f = t.function || t;
  const desc = f.description || '';
  const params = JSON.stringify(f.parameters || {});
  return { name: f.name, descLen: desc.length, paramLen: params.length, desc, params };
});
rows.sort((a, b) => (b.descLen + b.paramLen) - (a.descLen + a.paramLen));

console.log('=== PER-TOOL INJECTED PAYLOAD (every request) ===');
console.log('file:', file);
let td = 0, tp = 0;
rows.forEach((r, i) => {
  td += r.descLen; tp += r.paramLen;
  console.log(`${String(i + 1).padStart(2)}. ${r.name.padEnd(24)} desc=${String(r.descLen).padStart(6)} (~${String(Math.round(r.descLen / 4)).padStart(5)} tok)  params=${String(r.paramLen).padStart(6)}`);
});
console.log(`\nTOTAL descriptions: ${td} chars (~${Math.round(td / 4)} tok)`);
console.log(`TOTAL param schemas: ${tp} chars (~${Math.round(tp / 4)} tok)`);
console.log(`GRAND TOTAL: ${td + tp} chars (~${Math.round((td + tp) / 4)} tok)`);
console.log(`tools count: ${tools.length}`);

// Redundancy: sentences appearing in multiple tool descriptions
const sentMap = new Map();
for (const r of rows) {
  const seen = new Set();
  for (const s of r.desc.split(/(?<=[.:;!?])\s+|\n{2,}|\n(?=- )/)) {
    const ns = s.replace(/\s+/g, ' ').trim();
    if (ns.length < 60 || seen.has(ns)) continue;
    seen.add(ns);
    if (!sentMap.has(ns)) sentMap.set(ns, new Set());
    sentMap.get(ns).add(r.name);
  }
}
const shared = [...sentMap.entries()].filter(([, s]) => s.size > 1);
console.log('\n=== SENTENCES SHARED ACROSS TOOL DESCRIPTIONS ===');
let w = 0;
shared.sort((a, b) => b[0].length * (b[1].size - 1) - a[0].length * (a[1].size - 1)).forEach(([s, set]) => {
  const ww = s.length * (set.size - 1); w += ww;
  console.log(`x${set.size} len=${s.length} waste~${ww} [${[...set].join(', ')}]`);
  console.log('   "' + s.slice(0, 170) + '"');
});
console.log('shared-sentence waste:', w, '~', Math.round(w / 4), 'tok');

// near-duplicate paragraphs across tool descriptions (Jaccard on 5-grams)
function shingles(s, k = 6) {
  const words = s.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
  const set = new Set();
  for (let i = 0; i + k <= words.length; i++) set.add(words.slice(i, i + k).join(' '));
  return set;
}
const paras = [];
for (const r of rows) {
  for (const p of r.desc.split(/\n{2,}/)) {
    if (p.trim().length < 120) continue;
    paras.push({ tool: r.name, text: p.trim(), sh: shingles(p) });
  }
}
const near = [];
for (let i = 0; i < paras.length; i++) for (let j = i + 1; j < paras.length; j++) {
  if (paras[i].tool === paras[j].tool) continue;
  const a = paras[i].sh, b = paras[j].sh;
  if (!a.size || !b.size) continue;
  let inter = 0; for (const x of a) if (b.has(x)) inter++;
  const jac = inter / (a.size + b.size - inter);
  if (jac > 0.35) near.push({ jac, i, j });
}
