// common prefix/suffix among the bodies
function commonPrefix(a, b) { let i = 0; while (i < a.length && i < b.length && a[i] === b[i]) i++; return i; }
function commonSuffix(a, b) { let i = 0; while (i < a.length && i < b.length && a[a.length - 1 - i] === b[b.length - 1 - i]) i++; return i; }
const bodies = entries.map(e => e.body);
let pre = bodies[0], suf = bodies[0];
for (const b of bodies.slice(1)) {
  const p = commonPrefix(pre, b); pre = pre.slice(0, p);
  const s = commonSuffix(suf, b); suf = suf.slice(suf.length - s);
}
console.log('\ncommon prefix len:', pre.length);
console.log('common suffix len:', suf.length);
const identical = pre.length + suf.length;
console.log('shared (identical) portion per entry:', identical, 'chars');
const totalBlock = bodies.reduce((a, b) => a + b.length, 0);
const uniquePortion = bodies.reduce((a, b) => a + (b.length - identical), 0);
console.log('total across 4 entries:', totalBlock, 'chars');
console.log('if deduped (keep shared text once + per-plugin delta):', identical + uniquePortion, 'chars');
