const files = fs.readdirSync(DIR).filter(f => f.startsWith('inj_'));
for (const f of files) {
  const txt = fs.readFileSync(DIR + '/' + f, 'utf8');
  if (txt.length < 1200) continue;
  // repeated sentences
  const counts = new Map();
  for (const s of txt.split(/(?<=[.:;!?])\s+|\n+/)) {
    const ns = s.replace(/\s+/g, ' ').trim();
    if (ns.length < 50) continue;
    counts.set(ns, (counts.get(ns) || 0) + 1);
  }
  const rep = [...counts.entries()].filter(([, v]) => v > 1);
  const repWaste = rep.reduce((a, [s, v]) => a + s.length * (v - 1), 0);
  // repeated paragraphs (exact)
  const pc = new Map();
  for (const p of txt.split(/\n{2,}/)) { const np = p.trim(); if (np.length >= 80) pc.set(np, (pc.get(np) || 0) + 1); }
  const prep = [...pc.entries()].filter(([, v]) => v > 1);
  const prepWaste = prep.reduce((a, [p, v]) => a + p.length * (v - 1), 0);
  if (repWaste || prepWaste) {
