{"content": "#!/usr/bin/env node
/**
 * ZCode 提示词精简补丁
 *
 * 两个独立、可单独回滚的部分：
 *   A. Agent 工具描述去重
 *      根因：bho() 把各插件 agent 平铺进 "Available agent types"，未按描述去重，
 *            导致 4 个文档插件各自声明的同一个 visual-judge 被打印 4 遍。
 *      改法：仅在「显示列表」按 description 去重。所有 agent 仍全部注册、仍可按名调用，
 *            因此零能力损失。省 ~914 tok/请求。
 *   B. 关闭动态工作流 + off-peak 工具族
 *      依据：这两个开关的产品默认值就是 false（CodeApp 里初始化为 !1），数据库
 *            dwf_run / workflow_run / workflow_definition / session_task_link 均为 0 行，
 *            7 天日志中 workflow(9) / offpeak(2) 工具调用次数为 0。
 *      改法：把运行时开关表达式强制为 false —— 即产品自身的默认状态，非新增行为。
 *            省 ~5,896 tok/请求。
 *
 * 用法:
 *   node patch-zcode-prompt-trim.js status   # 查看状态
 *   node patch-zcode-prompt-trim.js apply    # 应用
 *   node patch-zcode-prompt-trim.js revert   # 回滚
 */
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const BUNDLE = 'C:\\Users\\UserX\\AppData\\Local\\Programs\\ZCode\\resources\\glm\\zcode.cjs';
const BACKUP_DIR = 'C:\\Users\\UserX\\.zcode\\backup\\zcode-cjs';
const SNAP_PREFIX = 'zcode.cjs.pre-trim-';

// ---- A. Agent 描述去重 ----
const A_FROM = 'function bho(e,t={}){let n=$vn(e);';
const A_TO = 'function bho(e,t={}){let _seen=new Set,n=$vn(e).filter(_a=>!_seen.has(_a.description)&&(_seen.add(_a.description),!0));';

// ---- B1. 动态工作流开关强制关闭 ----
const B1_FROM = 'dynamicWorkflowEnabled:"dynamicWorkflowEnabled"in t&&t.dynamicWorkflowEnabled===!0||e.appRuntimePreferences.dynamicWorkflowEnabled===!0,';
const B1_TO = 'dynamicWorkflowEnabled:!1,';

// ---- B2. off-peak 开关强制关闭 ----
const B2_FROM = '"offPeakToolEnabled"in t&&t.offPeakToolEnabled===!0||e.appRuntimePreferences.offPeakToolEnabled===!0?{offPeakPort:dKo(e,()=>T)}:{}';
const B2_TO = '!1?{offPeakPort:dKo(e,()=>T)}:{}';

const PARTS = [
  { id: 'A  agent-desc-dedupe', from: A_FROM, to: A_TO },
  { id: 'B1 workflow-off', from: B1_FROM, to: B1_TO },
  { id: 'B2 offpeak-off', from: B2_FROM, to: B2_TO },
];

function count(hay, needle) { return hay.split(needle).length - 1; }

function checkSyntax(file) {
  try {
    execFileSync(process.execPath, ['--check', file], { stdio: 'pipe' });
    return null;
  } catch (e) {
    return (e.stderr || e.stdout || Buffer.from('')).toString().slice(0, 800);
  }
}

function snapshots() {
  return fs.existsSync(BACKUP_DIR)
    ? fs.readdirSync(BACKUP_DIR).filter((f) => f.startsWith(SNAP_PREFIX)).sort()
    : [];
}

function status() {
  const src = fs.readFileSync(BUNDLE, 'utf8');
  console.log(`bundle : ${BUNDLE}`);
  console.log(`  size  : ${fs.statSync(BUNDLE).size}`);
  console.log(`  mtime : ${fs.statSync(BUNDLE).mtime.toISOString()}`);
  console.log('');
  for (const p of PARTS) {
    const fromN = count(src, p.from), toN = count(src, p.to);
    const state = fromN === 1 && toN === 0 ? '未应用' : fromN === 0 && toN === 1 ? '已应用' : '异常';
    console.log(`  ${p.id.padEnd(24)} ${state}  (from=${fromN}, to=${toN})`);
  }
  const media = count(src, 'dwa=6*1024*1024');
  console.log(`\n  媒体补丁 (dwa=6MiB): ${media === 1 ? '在' : '不在'}`);
  const snaps = snapshots();
  console.log(`  回滚快照: ${snaps.length ? snaps.join(', ') : '(无)'}`);
}

function apply() {
  const src = fs.readFileSync(BUNDLE, 'utf8');

  // 幂等 + 唯一性校验
  const pending = [];
  for (const p of PARTS) {
    const fromN = count(src, p.from), toN = count(src, p.to);
    if (fromN === 0 && toN === 1) { console.log(`[跳过] ${p.id} 已应用`); continue; }
    if (fromN !== 1 || toN !== 0) {
      throw new Error(`${p.id}: 锚点唯一性校验失败 (from=${fromN}, to=${toN})，为安全起见终止。`);
    }
    pending.push(p);
  }
  if (!pending.length) { console.log('\n全部已应用，无需操作。'); return; }

  // 备份
  fs.mkdirSync(BACKUP_DIR, { recursive: true });
  const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
  const backup = path.join(BACKUP_DIR, `${SNAP_PREFIX}${stamp}`);
  fs.copyFileSync(BUNDLE, backup);
  console.log(`\n已备份 -> ${backup}`);

  // 替换 + 语法校验
  let out = src;
  for (const p of pending) {
    out = out.replace(p.from, p.to);
    console.log(`[替换] ${p.id}`);
  }
  const tmp = BUNDLE + '.trimpatch.cjs';
  fs.writeFileSync(tmp, out, 'utf8');
  const err = checkSyntax(tmp);
  if (err) { fs.unlinkSync(tmp); throw new Error('语法校验失败，已放弃写入:\n' + err); }
  console.log('语法校验通过 (node --check)');

  // 原子替换
  fs.copyFileSync(tmp, BUNDLE);
  fs.unlinkSync(tmp);

  fs.writeFileSync(path.join(BACKUP_DIR, 'LAST_TRIM_PATCH.txt'),
    `patched_at=${new Date().toISOString()}\nparts=${pending.map((p) => p.id).join(',')}\nbundle=${BUNDLE}\nbackup=${backup}\n`);
  console.log('\n补丁已应用。请完全退出并重启 ZCode 生效。');
  console.log(`回滚: node "${path.basename(__filename)}" revert`);
}

function revert() {
  const snaps = snapshots();
  if (!snaps.length) throw new Error('未找到回滚快照。');
  const newest = path.join(BACKUP_DIR, snaps[snaps.length - 1]);
  const err = checkSyntax(newest);
  if (err) throw new Error('快照语法校验失败，拒绝回滚:\n' + err);
  // 先备份当前状态，避免回滚丢失现场
  const cur = path.join(BACKUP_DIR, `zcode.cjs.before-revert-${Date.now()}`);
  fs.copyFileSync(BUNDLE, cur);
  fs.copyFileSync(newest, BUNDLE);
  console.log(`已回滚 -> ${newest}`);
  console.log(`回滚前的状态已另存 -> ${cur}`);
  console.log('请完全退出并重启 ZCode 生效。');
}

const cmd = (process.argv[2] || 'status').toLowerCase();
try {
  if (cmd === 'apply') apply();
  else if (cmd === 'revert' || cmd === 'rollback') revert();
  else status();
} catch (e) {
  console.error('ERROR: ' + e.message);
  process.exit(1);
}
