{"content": "#!/usr/bin/env node
/**
 * ZCode 提示词精简补丁 v2（适配 2026-10-23 更新后的 bundle）
 *
 * 旧版（0.13.x，14.8MB）的补丁见 patch-zcode-prompt-trim.js（已随更新失效，保留作参考）。
 * 本脚本仅适用于当前版本；所有锚点带唯一性校验，失配即安全终止，不会写坏文件。
 *
 * 部分：
 *   A  Agent 类型列表去重
 *      新版把 agent 列表从「工具描述内嵌」改为「环境附件」（R5o → formatAgentListingDelta）。
 *      四个文档插件仍各自声明同一个 visual-judge，附件里照样重复 4 遍。
 *      改法：显示行按 description 去重，addedTypes 保持完整（保证增量追踪不会把
 *      未显示的同名 agent 在后续会话中重新列出）。agent 仍全部注册、可按名调用。
 *   B1 会话级 workflow 开关强制 false（Dfi 合并结果）
 *   B2 off-peak 端口强制不注入
 *   B3 workflow 注册门 qkt() 强制 false（同时使 Agent 描述的 workflow 段落消失）
 *   B4 cron 注册门 includeAutomation 强制 false
 *   M  恢复媒体预算补丁（上版为 dwa=40MiB→6MiB，新版变量改名 sFa）
 *
 * 用法:
 *   node patch-zcode-prompt-trim2.js status
 *   node patch-zcode-prompt-trim2.js apply
 *   node patch-zcode-prompt-trim2.js revert
 */
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const BUNDLE = 'C:\\Users\\UserX\\AppData\\Local\\Programs\\ZCode\\resources\\glm\\zcode.cjs';
const BACKUP_DIR = 'C:\\Users\\UserX\\.zcode\\backup\\zcode-cjs';
const SNAP_PREFIX = 'zcode.cjs.pre-trim2-';
// 新版 bundle 体积守卫：防止把旧版快照误写回新版文件
const SIZE_MIN = 15_000_000, SIZE_MAX = 16_000_000;

const PARTS = [
  {
    id: 'A  agent-list-dedupe',
    from: 'let c={addedTypes:i.map(u=>u.name),addedLines:i.map(u=>qNo(u,e)),removedTypes:a,isInitial:t.size===0,showConcurrencyNote:!0};',
    to: 'let c=(()=>{let _d=new Set,_l=[];for(let u of i){let _k=JSON.stringify([u.description,u.tools??null]);if(_d.has(_k))continue;_d.add(_k);_l.push(qNo(u,e))}return{addedTypes:i.map(u=>u.name),addedLines:_l,removedTypes:a,isInitial:t.size===0,showConcurrencyNote:!0}})();',
  },
  {
    id: 'B1 session-wf-gate',
    from: '...Dfi({dynamicWorkflowEnabled:"dynamicWorkflowEnabled"in t?t.dynamicWorkflowEnabled:void 0,dynamicWorkflowMode:"dynamicWorkflowMode"in t?t.dynamicWorkflowMode:void 0},e.appRuntimePreferences)',
    to: '{dynamicWorkflowEnabled:!1,dynamicWorkflowToolsOnDemand:!1}',
  },
  {
    id: 'B2 offpeak-off',
    from: '"offPeakToolEnabled"in t&&t.offPeakToolEnabled===!0||e.appRuntimePreferences.offPeakToolEnabled===!0?{offPeakPort:yfi(e,()=>x)}:{}',
    to: '!1?{offPeakPort:yfi(e,()=>x)}:{}',
  },
  {
    id: 'B3 workflow-gate-off',
    from: 'function qkt(e){return e.config.dynamicWorkflowEnabled!==!1&&e.dynamicWorkflowToolsActivated}',
    to: 'function qkt(e){return !1}',
  },
  {
    id: 'B4 cron-gate-off',
    from: 'includeAutomation:!!t.automationPort&&e.config.taskType!=="subagent_child"',
    to: 'includeAutomation:!1',
  },
  {
    id: 'M  media-budget-6MiB',
    from: 'sFa=40*1024*1024',
    to: 'sFa=6*1024*1024',
  },
];

function count(hay, needle) { return hay.split(needle).length - 1; }

function checkSyntax(file) {
  try {
    execFileSync(process.execPath, ['--check', file], { stdio: 'pipe' });
    return null;
  } catch (e) {
    return (e.stderr || e.stdout || Buffer.from('')).toString().slice(0, 800);
  }
}

function snapshots() {
  return fs.existsSync(BACKUP_DIR)
    ? fs.readdirSync(BACKUP_DIR).filter((f) => f.startsWith(SNAP_PREFIX)).sort()
    : [];
}

function guard() {
  const st = fs.statSync(BUNDLE);
  if (st.size < SIZE_MIN || st.size > SIZE_MAX) {
    throw new Error(`bundle 体积 ${st.size} 超出本脚本适配范围 [${SIZE_MIN},${SIZE_MAX}]，可能又是新版本，拒绝操作。`);
  }
}

function status() {
  guard();
  const src = fs.readFileSync(BUNDLE, 'utf8');
  console.log(`bundle : ${BUNDLE}`);
  console.log(`  size  : ${fs.statSync(BUNDLE).size}  mtime : ${fs.statSync(BUNDLE).mtime.toISOString()}`);
  console.log('');
  for (const p of PARTS) {
    const fromN = count(src, p.from), toN = count(src, p.to);
    let state;
    if (fromN === 1 && toN === 0) state = '未应用';
    else if (fromN === 0 && toN >= 1) state = '已应用';
    else if (fromN === 1 && toN >= 1) state = '异常(同时存在)';
    else state = '失配(代码已变)';
    console.log(`  ${p.id.padEnd(22)} ${state}  (from=${fromN}, to=${toN})`);
  }
  const snaps = snapshots();
  console.log(`\n  回滚快照: ${snaps.length ? snaps.join(', ') : '(无)'}`);
}

function apply() {
  guard();
  const src = fs.readFileSync(BUNDLE, 'utf8');
  const pending = [];
  for (const p of PARTS) {
    const fromN = count(src, p.from), toN = count(src, p.to);
    if (fromN === 0 && toN >= 1) { console.log(`[跳过] ${p.id} 已应用`); continue; }
    if (fromN !== 1 || toN !== 0) {
      throw new Error(`${p.id}: 锚点唯一性校验失败 (from=${fromN}, to=${toN})，为安全起见终止。可能 bundle 又更新了，请更新本脚本的锚点。`);
    }
    pending.push(p);
  }
  if (!pending.length) { console.log('\n全部已应用，无需操作。'); return; }

  fs.mkdirSync(BACKUP_DIR, { recursive: true });
  const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
  const backup = path.join(BACKUP_DIR, `${SNAP_PREFIX}${stamp}`);
  fs.copyFileSync(BUNDLE, backup);
  console.log(`\n已备份 -> ${backup}`);

  let out = src;
  for (const p of pending) { out = out.replace(p.from, p.to); console.log(`[替换] ${p.id}`); }
  const tmp = BUNDLE + '.trimpatch2.cjs';
  fs.writeFileSync(tmp, out, 'utf8');
  const err = checkSyntax(tmp);
  if (err) { fs.unlinkSync(tmp); throw new Error('语法校验失败，已放弃写入:\n' + err); }
  console.log('语法校验通过 (node --check)');

  fs.copyFileSync(tmp, BUNDLE);
  fs.unlinkSync(tmp);

  fs.writeFileSync(path.join(BACKUP_DIR, 'LAST_TRIM2_PATCH.txt'),
