  ...['documents', 'pdf', 'presentations', 'spreadsheets']
    .map((p) => `AppData/Local/Programs/ZCode/resources/glm/packages/${p}-plugin/agents/visual-judge.md`),
];

const BK = 'C:/Users/UserX/.zcode/backup/zcode-cjs/visual-judge-20261027';
fs.mkdirSync(BK, { recursive: true });

const MODEL_LINE = /^model:.*\r?\n/m;
let fixed = 0;

for (const rel of files) {
  const abs = path.join(ROOT, rel);
  const src = fs.readFileSync(abs, 'utf8');
  if (!MODEL_LINE.test(src)) {
    console.log('skip (no model line):', rel);
    continue;
  }
  const flat = rel.split('/').join('_');
  fs.writeFileSync(path.join(BK, flat), src, 'utf8');
  const out = src.replace(MODEL_LINE, '');
  fs.writeFileSync(abs, out, 'utf8');
  console.log(`fixed: ${rel}  ${src.length} -> ${out.length}`);
  fixed++;
}

